import os
import sys

def fork_and_wait():
    pid = os.fork()
    if pid == 0:
        # Ребёнок
        sys.exit(0)
    else:
        # Родитель
        pid2 = os.fork()
        if pid2 == 0:
            sys.exit(0)
        else:
            os.waitpid(pid, 0)
            os.waitpid(pid2, 0)

fork_and_wait()

